changeSet.sql:
CREATE SEQUENCE IF NOT EXISTS krrg_settings_id_seq;
ALTER TABLE krrg_settings ALTER COLUMN id SET DEFAULT nextval('krrg_settings_id_seq');
SELECT setval('krrg_settings_id_seq', COALESCE((SELECT MAX(id) FROM krrg_settings), 0));

UPDATE krrg_setting_groups SET sort_order = 1 WHERE code = 'general';
UPDATE krrg_setting_groups SET sort_order = 2 WHERE code = 'cron';
UPDATE krrg_setting_groups SET sort_order = 3 WHERE code = 'folder';
UPDATE krrg_setting_groups SET sort_order = 4 WHERE code = 'ai';
UPDATE krrg_setting_groups SET sort_order = 5 WHERE code = 'gmail';
UPDATE krrg_setting_groups SET sort_order = 9 WHERE code = 'admin';
